// Stand-ins for the API of the Strudel packages that need a browser (list generated by
// js/tools/gen-browser-api.mjs). User code can call every one of these names. Phase by phase,
// Concha replaces them with native implementations (sound, MIDI, samples, visuals...).
//
// Kinds of stand-in:
//  - output methods (midi, osc, dough...): the haps go to Concha's outbox with that kind instead
//    of the default sound output, as Strudel does with pat.onSchedule(..., dominant = true);
//  - visual and other pattern methods (pianoroll, scope...): return the pattern unchanged;
//  - widgets (_pianoroll, _scope...): registered with the transpiler, as in strudel.cc;
//  - functions: return their first argument (samples('...') still awaits fine), constants keep
//    their value, classes become inert objects.
import { Pattern, isPattern, silence, ref, registerControl } from '@strudel/core';
import { registerWidgetType } from '@strudel/transpiler';
import api from './generated/browser-api.json';

// Events of output methods are collected here during concha.query().
export const outbox = { events: null };

const num = (f) => (f === undefined || f === null ? undefined : f.valueOf());

// One scheduled event. begin/end: the hap's whole, in cycles. value: hap.value (object). locs: code
// ranges [start, end) that produced the hap, for highlighting. kind: 'sound' (default output),
// 'midimsg' (raw MIDI, src/midi.mjs) or the name of an output method not implemented yet.
export function toEvent(kind, hap, extra) {
  const value = typeof hap.value === 'object' && hap.value !== null ? hap.value : { value: hap.value };
  const locs = (hap.context?.locations ?? []).map((l) => [l.start, l.end]);
  // dur: hap.duration, which includes clip (what webaudioOutput passes to superdough), in cycles.
  const e = { kind, begin: num(hap.whole.begin), end: num(hap.whole.end), dur: num(hap.duration), value, locs, ...extra };
  if (hap.context?.conchaVisual) e.vis = hap.context.conchaVisual; // a channel of the oscilloscope (visuals.mjs)
  return e;
}

// midi, mqtt, robot and serial are real (src/midi.mjs, src/io.mjs); the others go out with their
// name as kind until they are implemented.
export const outputMethods = ['osc', 'dough', 'csound', 'csoundm'];

class Inert {
  constructor() {
    return new Proxy(this, { get: (t, k) => (k in t ? t[k] : inertFn) });
  }
}
function inertFn(...args) {
  return args[0];
}

// Functions whose stand-in needs a specific behaviour so that code using them evaluates as on strudel.cc.
const special = {
  // codemirror sliders: the transpiler turns slider(v) into sliderWithID(id, v). The value is read at
  // query time, so Concha can move it later (setSlider).
  sliderValues: {},
  sliderWithID(id, value) {
    special.sliderValues[id] = value;
    return ref(() => special.sliderValues[id]);
  },
  slider: (value) => value,
  getAudioContext: () => ({ currentTime: 0, sampleRate: 48000 }),
  getDrawContext: () => ({ clearRect() {}, fillText() {}, fillRect() {}, canvas: { width: 100, height: 100 } }),
  initAudio: async () => {},
  initAudioOnFirstClick: async () => {},
  samples: async (...args) => args[0],
};

export const stubGlobals = {};
export const setSlider = (id, value) => {
  special.sliderValues[id] = value;
};
const defined = (name) => name in globalThis || name in stubGlobals;

// webaudio's scopes and spectrum tag the haps with `analyze` (the native visualiser will read it).
const analysing = ['scope', 'tscope', 'fscope', 'spectrum'];

export function installStubs() {
  // codemirror registers this control; it only colours code, but it must exist.
  if (!defined('markcss')) Object.assign(stubGlobals, registerControl('markcss'));

  const methodNames = new Set();
  for (const pkg of Object.values(api)) {
    pkg.methods.forEach((m) => methodNames.add(m));
    pkg.widgets.forEach((w) => {
      registerWidgetType(w);
      methodNames.add(w);
    });
  }

  for (const name of methodNames) {
    if (Pattern.prototype[name]) continue; // already provided by a package Concha runs
    if (outputMethods.includes(name)) {
      Pattern.prototype[name] = function (...args) {
        return this.onSchedule((hap) => {
          outbox.events?.push(toEvent(name, hap, { args }));
        }, true);
      };
    } else if (analysing.includes(name)) {
      Pattern.prototype[name] = function (config = {}) {
        return this.analyze(config.id ?? 1);
      };
    } else {
      Pattern.prototype[name] = function () {
        return this;
      };
    }
  }

  for (const pkg of Object.values(api)) {
    for (const [name, info] of Object.entries(pkg.exports)) {
      if (defined(name)) continue;
      if (name in special) stubGlobals[name] = special[name];
      else if (methodNames.has(name))
        stubGlobals[name] = (...args) => {
          const pat = args[args.length - 1];
          return isPattern(pat) ? pat[name](...args.slice(0, -1)) : silence;
        };
      else if (info.kind === 'value') stubGlobals[name] = info.value;
      else if (info.kind === 'class') stubGlobals[name] = Inert;
      else stubGlobals[name] = inertFn;
    }
  }
  for (const [name, fn] of Object.entries(special)) if (!defined(name)) stubGlobals[name] = fn;
  return stubGlobals;
}
